// Code generated by fin-protoc. DO NOT EDIT.
//
// Decoded strings borrow from the input buffer and stay valid only while the
// input bytes do; deinit frees only the outer repeat slices allocated by
// decode. Requires the `binary_codec` module (fin-proto-runtime-bin-zig).

const std = @import("std");
const codec = @import("binary_codec");

pub const Instruction = struct {
    instr_id: u64,
    instr_type: u16,
    target_type: u8,
    target: []const u8,
    expiry_ns: u64,
    operator: []const u8,
    ts_ns: u64,

    pub fn encode(self: *const Instruction, buf: *codec.Buffer) !void {
        try buf.put(u64, self.instr_id);
        try buf.put(u16, self.instr_type);
        try buf.put(u8, self.target_type);
        try codec.putCharArray(buf, self.target, 32);
        try buf.put(u64, self.expiry_ns);
        try codec.putCharArray(buf, self.operator, 16);
        try buf.put(u64, self.ts_ns);
    }

    pub fn decode(allocator: std.mem.Allocator, r: *codec.Reader) codec.DecodeError!Instruction {
        _ = allocator;
        const instr_id = try r.get(u64);
        const instr_type = try r.get(u16);
        const target_type = try r.get(u8);
        const target = try codec.getCharArray(r, 32);
        const expiry_ns = try r.get(u64);
        const operator = try codec.getCharArray(r, 16);
        const ts_ns = try r.get(u64);
        return .{
            .instr_id = instr_id,
            .instr_type = instr_type,
            .target_type = target_type,
            .target = target,
            .expiry_ns = expiry_ns,
            .operator = operator,
            .ts_ns = ts_ns,
        };
    }

    pub fn deinit(self: Instruction, allocator: std.mem.Allocator) void {
        _ = self;
        _ = allocator;
    }

    pub fn eql(self: Instruction, other: Instruction) bool {
        if (self.instr_id != other.instr_id) return false;
        if (self.instr_type != other.instr_type) return false;
        if (self.target_type != other.target_type) return false;
        if (!std.mem.eql(u8, self.target, other.target)) return false;
        if (self.expiry_ns != other.expiry_ns) return false;
        if (!std.mem.eql(u8, self.operator, other.operator)) return false;
        if (self.ts_ns != other.ts_ns) return false;
        return true;
    }
};

test "test_instruction_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = Instruction{
        .instr_id = 123456789,
        .instr_type = 1234,
        .target_type = 42,
        .target = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        .expiry_ns = 123456789,
        .operator = "aaaaaaaaaaaaaaaa",
        .ts_ns = 123456789,
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try Instruction.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    try std.testing.expect(msg.eql(decoded));
}
